-- Generated by scripts/build-ai-server-bound-edits-catalog.ts.
-- Apply core first, deploy ask-bob AND bob-worker, then activate this publication.
begin;
do $server_bound_edits_catalog$
declare contracts jsonb:=$bound_edit_contracts$[
  {
    "name": "read_project_edit_context",
    "description": "Read complete editable project descriptions or solutions. Returns server-bound edit_ref selections and content; never construct a database identity or version. selected_solutions includes each selected scope separately. Use next_ref unchanged for the next page. Re-read after a conflict and reconsider the intended change.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "resource": {
          "type": "string",
          "enum": [
            "project_description",
            "selected_solutions",
            "solutions"
          ]
        },
        "query": {
          "type": [
            "string",
            "null"
          ]
        },
        "next_ref": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
        "resource",
        "query",
        "next_ref"
      ]
    }
  },
  {
    "name": "edit_project_record",
    "description": "Revise the record returned by read_project_edit_context using only the requested changes. Never creates an alternative. Existing fields, measurements, image links and nested decisions are preserved. Editing a selected solution also advances that same selection atomically. Changes use content paths and JSON-encoded values. Text fields: /description, /title, /assumptions, /tradeoffs. Design fields: /design_intent/summary or /purpose; features and choices use zero-based indices from the read. Append a feature or choice at /design_intent/features/- or /choices/- without id (feature source_ref is server-owned). Replace individual content fields; remove a feature/choice explicitly. Identity and source-link edits are unavailable here. A null design_intent can be initialized by setting its summary (purpose defaults to concept). Changes reset alignment to draft unless /design_intent/alignment is explicitly set with an honest status and basis. A failed edit must never be replaced with a create.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "edit_ref": {
          "type": "string"
        },
        "changes": {
          "type": "array",
          "minItems": 1,
          "maxItems": 40,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "op": {
                "type": "string",
                "enum": [
                  "set",
                  "append_text",
                  "remove"
                ]
              },
              "path": {
                "type": "string"
              },
              "value_json": {
                "type": [
                  "string",
                  "null"
                ],
                "description": "JSON-encoded new value. null only for remove. append_text appends the decoded string verbatim."
              }
            },
            "required": [
              "op",
              "path",
              "value_json"
            ]
          }
        },
        "reason": {
          "type": "string"
        },
        "request_quote": {
          "type": "string"
        }
      },
      "required": [
        "edit_ref",
        "changes",
        "reason",
        "request_quote"
      ]
    }
  }
]$bound_edit_contracts$::jsonb;
 policies jsonb:=$bound_edit_policies$[
  {
    "name": "edit_project_record",
    "description": "Apply requested content changes to a previously read project description or solution.",
    "how_to": "Read the edit context first. Send only edit_ref, content changes and a reason. The server binds the current request and preserves unmodified sources and decisions. A selected solution revision and its selected target advance together. On conflict re-read and reconsider; never create a replacement. Changes are applied sequentially. Source identity edits are not part of this first adapter.",
    "schema_version": 1,
    "active": true,
    "always_load": true,
    "preload_phases": []
  },
  {
    "name": "read_project_edit_context",
    "description": "Read complete project description or solution content for a server-bound edit.",
    "how_to": "Select a returned edit_ref. The runtime owns identity, scope, versions and unchanged data. selected_solutions returns exact selected revisions and scopes; solutions returns alternatives. Use next_ref for further results.",
    "schema_version": 1,
    "active": true,
    "always_load": true,
    "preload_phases": []
  }
]$bound_edit_policies$::jsonb;
 append jsonb:=$bound_edit_append$[
  {
    "key": "tools.save_project_solution",
    "text": " Existing solution edits now use read_project_edit_context and edit_project_record: choose a returned edit_ref and send only the content delta. This legacy tool remains for explicitly new alternatives only. A failed revision never authorizes a create. The bound editor preserves sources, nested choices and original identity; selected context advances the selected revision atomically."
  },
  {
    "key": "tools.save_project_description",
    "text": " Superseded for new turns by read_project_edit_context(resource=project_description) and edit_project_record. Do not copy timestamps or the unchanged description. The runtime binds the exact read and preserves existing text when appending."
  }
]$bound_edit_append$::jsonb;
 patch jsonb; policy jsonb; prior shared.ai_prompt_versions; template shared.ai_prompt_versions;
 prompt_uuid uuid; version_uuid uuid; next_version integer; definition jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 select v.* into template from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.save_project_description';
 if not found then raise exception 'bound_edit_template_missing'; end if;
 for patch in select value from jsonb_array_elements(contracts) loop
  select value into policy from jsonb_array_elements(policies) where value->>'name'=patch->>'name';
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.'||(patch->>'name');
  if not found then
   insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind)
    values('bob','tools.'||(patch->>'name'),policy->>'description',policy->>'description','','','tool_contract') returning id into prompt_uuid;
   prior:=template;
  else prompt_uuid:=prior.prompt_id;
  end if;
  definition:=prior.definition||patch||jsonb_build_object('handler',patch->>'name','required_parameters',patch#>'{parameters,required}','optional_parameters','[]'::jsonb,'additional_description',policy->>'how_to');
  definition:=jsonb_set(definition,'{envelope,schema_version}','1'::jsonb);
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prompt_uuid;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prompt_uuid,next_version,'tool_contract',1,jsonb_build_object('publication','server-bound-edits','server_fields',case when patch->>'name'='edit_project_record' then ' ["request_quote"]'::jsonb else '[]'::jsonb end),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object('tools.'||(patch->>'name'),version_uuid);
 end loop;
 for patch in select value from jsonb_array_elements(append) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=patch->>'key';
  if not found then raise exception 'bound_edit_legacy_contract_missing'; end if;
  definition:=jsonb_set(prior.definition,'{additional_description}',to_jsonb(coalesce(prior.definition->>'additional_description','')||(patch->>'text')));
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','server-bound-edits'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.tools' for update of p;
 if not found then raise exception 'bound_edit_toolbox_missing'; end if;
 definition:=prior.definition;
 for policy in select value from jsonb_array_elements(policies) loop
  insert into bob.tool_catalog(name,description,how_to,schema_version,always_load,preload_phases,active)
   values(policy->>'name',policy->>'description',policy->>'how_to',(policy->>'schema_version')::integer,(policy->>'always_load')::boolean,array(select jsonb_array_elements_text(policy->'preload_phases')),(policy->>'active')::boolean)
   on conflict(name) do nothing;
  if not exists(select 1 from jsonb_array_elements(definition->'catalog') r where r->>'name'=policy->>'name') then
   definition:=jsonb_set(definition,'{catalog}',definition->'catalog'||jsonb_build_array(policy));
  end if;
  if not definition->'contract_keys'?('tools.'||(policy->>'name')) then
   definition:=jsonb_set(definition,'{contract_keys}',definition->'contract_keys'||jsonb_build_array('tools.'||(policy->>'name')));
  end if;
  definition:=jsonb_set(definition,'{shelves}',(select jsonb_agg(case when shelf->>'label'='Project records and memory' and not shelf->'tools'?(policy->>'name') then jsonb_set(shelf,'{tools}',shelf->'tools'||jsonb_build_array(policy->>'name')) else shelf end) from jsonb_array_elements(definition->'shelves') shelf));
 end loop;
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','server-bound-edits'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.tools',version_uuid);
 perform shared.activate_ai_catalog('bob',activation);
end $server_bound_edits_catalog$;
commit;
